head.script:
// 테스트 설명, 유효성 값 설정
// displayFormat 분할 _2 : dataType='date' 축 (propval date 마스크 / 미설정 기본값 / date 마스크 적용 규칙 / ioFormat 길이 불일치)
scwin.tData = {
    "description" : "[column > P > displayFormat]<br/>Column 이 편집 상태가 아닐때 Column 값이 표시되는 포맷을 마스크 문자로 설정합니다.",
    "validation" : [
        "dataType='date' : 'y', 'M', 'd', 'E' 마스크 문자를 사용하여 포맷 설정",
        "displayFormat 속성값을 설정하지 않으면 dataType='date' : config.xml 의 WebSquare/gridView/dataType/date/@displayFormat 설정값인 'yyyy-MM-dd'",
        "dataType='date' 일때 'yyyy' 마스크는 년도와 매칭되며 네자리로 설정합니다.",
        "dataType='date' 일때 'MM' 마스크는 월과 매칭되며 두자리로 설정합니다.",
        "dataType='date' 일때 'dd' 마스크는 일과 매칭되며 두자리로 설정합니다.",
        "dataType='date' 일때 'E' 마스크는 요일과 매칭되며 한자리로 설정합니다.",
        "dataType='date' 일때 마스크 포맷 왼쪽과 오른쪽의 일반문자는 그대로 적용됩니다.",
        "dataType='date' 일때 내부 텍스트는 yyyyMMdd 형식으로 제공되어야 정상적으로 처리됩니다.",
        "dataType='date' 인 Column 에서 Cell 값의 길이가 ioFormat 속성값의 길이와 다르면 displayFormat 속성이 적용되지 않고 그대로 표시됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (가이드 예시 포맷)
    con_displayFormat.setSelectedIndex(1);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - raw     : 저장값 원문 표시 Column (dataType=text, readOnly)
//  - regDate : 검증 대상 Column (inputType=text, dataType=date, ioFormat=yyyyMMdd 고정, displayFormat 을 옵션값으로 설정)
//  - Row 0~1 : yyyyMMdd 형식 정상값 / Row 2 : 7자리(길이 불일치) / Row 3 : 구분자 포함 10자리(길이 불일치) / Row 4 : 8자리 ddMMyyyy 순서
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cDisplayFormat = con_displayFormat.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] regDate Column 은 inputType=text, dataType=date, ioFormat=yyyyMMdd 고정. 저장값 Column 은 원본 문자열\n[절차] displayFormat 선택 -> Target 재생성 -> (셀 표시값 확인) 클릭\n[확인] Row 별 저장값과 regDate 표시값 비교 (Row 4 는 일자-월-년도 순서로 저장된 8자리 값)"', '', 'label1');

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="raw" name="raw" dataType="text"></w2:column>';
    strDlt += '<w2:column id="regDate" name="regDate" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    let arrValue = ["20240315", "20251225", "2024315", "2024-03-15", "15032024"];
    let jsonData = [];
    for (let i = 0; i < arrValue.length; i++) {
        jsonData.push({ "raw" : arrValue[i], "regDate" : arrValue[i] });
    }
    dlt_bind.setJSON(jsonData, false);

    // regDate Column 속성
    let attrDate = ' inputType="text" dataType="date" ioFormat="yyyyMMdd"';
    if (cDisplayFormat !== '') {
        attrDate += ' displayFormat="' + cDisplayFormat + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:190px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column1" value="저장값"></w2:column>';
    strTarget += '<w2:column width="340" style="" inputType="text" id="column2" value="regDate (date)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" style="" inputType="text" dataType="text" id="raw" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="340" style="" id="regDate" value=""' + attrDate + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Row 별 저장값(getCellData) -> regDate 셀 표시값 출력
//  - validation 1, 3~7 : Row 0, 1 (yyyyMMdd 정상값) 의 표시값으로 마스크 문자별 적용 결과 확인
//  - validation 2 : displayFormat 미설정 시 Row 0, 1 표시값
//  - validation 8 : Row 4 (8자리, yyyyMMdd 가 아닌 순서) 표시값
//  - validation 9 : Row 2, 3 (ioFormat 과 길이가 다른 값) 표시값
scwin.btn_checkCell_onclick = function () {
    let colIndex = target1.getColumnIndex("regDate");
    let cnt = dlt_bind.getRowCount();
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + r + "_" + colIndex + "']");
        let cellText = td ? td.textContent : "";
        arr.push("Row " + r + " 저장값 : " + target1.getCellData(r, "regDate") + " -> 표시값 : " + cellText);
    }
    wf_body_bottom.getObj("scwin").setReturnValue(arr.join("\n"));
}
